import type {OutgoingMessage, SessionSummaryFrame} from './messages.js';

describe('the session_list wire frame', () => {
  it('is an outgoing message whose rows carry ISO strings and survive JSON unchanged', () => {
    const row: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: new Date('2026-01-01T00:00:00.000Z').toISOString(),
      updatedAt: new Date('2026-01-01T00:05:00.000Z').toISOString(),
      entryCount: 2,
    };
    const frame: OutgoingMessage = {type: 'session_list', sessions: [row]};

    expect(JSON.parse(JSON.stringify(frame))).toEqual(frame);
  });
});
